// action
import * as actions from '../action/import.action'; // state

import { ImportStateRecord } from './import.state';
export const initialState = new ImportStateRecord();
export function reducer(state = initialState, {
  type,
  payload
}) {
  if (!type) {
    return state;
  }

  switch (type) {
    case actions.ActionTypes.UPLOAD_FILE:
      {
        return Object.assign({}, state, {
          uploadFileLoading: true,
          uploadFileLoaded: false,
          uploadFileFailed: false
        });
      }

    case actions.ActionTypes.UPLOAD_FILE_SUCCESS:
      {
        return Object.assign({}, state, {
          uploadFile: payload,
          uploadFileLoading: false,
          uploadFileLoaded: true,
          uploadFileFailed: false
        });
      }

    case actions.ActionTypes.UPLOAD_FILE_FAIL:
      {
        return Object.assign({}, state, {
          uploadFileLoading: false,
          uploadFileLoaded: false,
          uploadFileFailed: true
        });
      }

    default:
      {
        return state;
      }
  }
}
export const uploadFile = state => state.uploadFile;
export const uploadFileLoading = state => state.uploadFileLoading;
export const uploadFileLoaded = state => state.uploadFileLoaded;
export const uploadFileFailed = state => state.uploadFileFailed;
